CREATE OR REPLACE FUNCTION public.hod_wanted(p_world uuid, p_cx integer, p_cy integer, p_range integer, p_keeper uuid DEFAULT NULL::uuid)
 RETURNS TABLE(items text[], n integer)
 LANGUAGE sql
 STABLE
AS $function$
  with each_ as (
    select e.key as item, min((w.x - p_cx) ^ 2 + (w.y - p_cy) ^ 2) as d
    from hod_work(p_world, p_cx, p_cy, p_range) w cross join lateral jsonb_each_text(w.needed) e
    where e.value::int > 0 and (p_keeper is null or hod_work_mine(p_world, p_keeper, w.dir, w.x, w.y))
    group by e.key
  )
  select (array_agg(item order by d, item collate "C"))[1:idle_wants()], count(*)::int from each_
